    enum FillMode { Zeros, Ones, Random }

    static readonly Random Rng = new Random();

    static byte[] BuildFill(int size, FillMode mode)
    {
        var buf = new byte[size];
        switch (mode)
        {
            case FillMode.Zeros:
                for (int i = 0; i < buf.Length; i++) buf[i] = 0x00;
                break;
            case FillMode.Ones:
                for (int i = 0; i < buf.Length; i++) buf[i] = 0xFF;
                break;
            case FillMode.Random:
                Rng.NextBytes(buf);
                break;
        }
        return buf;
    }

    static bool IsRegionScannable(MEMORY_BASIC_INFORMATION mbi)
    {
        if (mbi.State != MEM_COMMIT) return false;
        if ((mbi.Protect & PAGE_GUARD) != 0) return false;
        if ((mbi.Protect & PAGE_NOACCESS) != 0) return false;
        uint writable = PAGE_READWRITE | PAGE_WRITECOPY | PAGE_EXECUTE_READWRITE | PAGE_EXECUTE_WRITECOPY;
        return (mbi.Protect & writable) != 0;
    }

    static bool OverwriteRemote(IntPtr hProcess, IntPtr address, int size, FillMode mode)
    {
        if (size == 0) return true;
        var fill = BuildFill(size, mode);
        if (WriteProcessMemory(hProcess, address, fill, size, out int w) && w == size) return true;
        if (!VirtualProtectEx(hProcess, address, size, PAGE_EXECUTE_READWRITE, out uint old)) return false;
        bool ok = WriteProcessMemory(hProcess, address, fill, size, out w) && w == size;
        VirtualProtectEx(hProcess, address, size, old, out uint _);
        return ok;
    }

    static int IndexOf(byte[] haystack, byte[] needle, int start = 0)
    {
        int len = haystack.Length - needle.Length;
        for (int i = start; i <= len; i++)
        {
            bool match = true;
            for (int j = 0; j < needle.Length; j++)
                if (haystack[i + j] != needle[j]) { match = false; break; }
            if (match) return i;
        }
        return -1;
    }

    static void EnableDebugPrivilege()
    {
        if (!OpenProcessToken(Process.GetCurrentProcess().Handle, TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY, out IntPtr hToken)) return;
        if (!LookupPrivilegeValue(null, "SeDebugPrivilege", out LUID luid)) return;
        var luidAttr = new LUID_AND_ATTRIBUTES { Luid = luid, Attributes = SE_PRIVILEGE_ENABLED };
        var tp = new TOKEN_PRIVILEGES { PrivilegeCount = 1, Privileges = luidAttr };
        AdjustTokenPrivileges(hToken, false, ref tp, Marshal.SizeOf(typeof(TOKEN_PRIVILEGES)), IntPtr.Zero, IntPtr.Zero);
    }

    static void EnableAnsiConsole()
    {
        var handle = GetStdHandle(-11);
        GetConsoleMode(handle, out uint mode);
        SetConsoleMode(handle, mode | 0x0004);
    }

    static void PrintBanner()
    {
        Console.ForegroundColor = ConsoleColor.Yellow;
        Console.WriteLine(" ____   ___   ___  __  __ ____  ____    _ __   __ ");
        Console.WriteLine("|  _ \\ / _ \\ / _ \\|  \\/  / ___||  _ \\  / \\\\ \\ / / ");
        Console.WriteLine("| | | | | | | | | | |\\/| \\___ \\| | | |/ _ \\\\ V /  ");
        Console.WriteLine("| |_| | |_| | |_| | |  | |___) | |_| / ___ \\| |   ");
        Console.WriteLine("|____/ \\___/ \\___/|_|  |_|____/|____/_/   \\_\\_|   ");
        Console.WriteLine(" ____ _     _____    _    _   _ _____ ____        ");
        Console.WriteLine("/ ___| |   | ____|  / \\  | \\ | | ____|  _ \\       ");
        Console.WriteLine("| |   | |   |  _|   / _ \\ |  \\| |  _| | |_) |     ");
        Console.WriteLine("| |___| |___| |___ / ___ \\| |\\  | |___|  _ <      ");
        Console.WriteLine(" \\____|_____|_____/_/   \\_\\_| \\_|_____|_| \\_\\     ");
        Console.WriteLine("\n                              made by Diff edited by hsmiku(added doomsday strings) ");
        Console.ResetColor();
    }
    static void Main()
    {
        EnableDebugPrivilege();
        EnableAnsiConsole();

        var procs = Process.GetProcessesByName("javaw");
        if (procs.Length == 0)
        {
            Console.WriteLine("[-] No javaw.exe process found");
            System.Threading.Thread.Sleep(3000);
            return;
        }

        PrintBanner();
        Console.WriteLine("[+] javaw.exe (4 targets, Random fill)");

        var proc = procs[0];
        Console.WriteLine("[+] Target PID: " + proc.Id);

        IntPtr hProcess = OpenProcess(PROCESS_ALL, false, proc.Id);
        if (hProcess == IntPtr.Zero)
        {
            Console.WriteLine("[-] OpenProcess failed");
            return;
        }

        var asciiPatterns = new List<byte[]>();
        var widePatterns = new List<byte[]>();
        foreach (var s in TargetStrings)
        {
            asciiPatterns.Add(Encoding.ASCII.GetBytes(s));
            widePatterns.Add(Encoding.Unicode.GetBytes(s));
        }

        long totalBytes = 0, asciiMatches = 0, wideMatches = 0, writeFailures = 0;
        long regionsScanned = 0, regionsSkipped = 0;

        IntPtr minAddr = new IntPtr(0x10000);
        IntPtr maxAddr = Environment.Is64BitProcess ? new IntPtr(long.MaxValue >> 16) : new IntPtr(0x7FFEFFFF);

        Console.WriteLine("[*] Scanning...");
        var sw = Stopwatch.StartNew();

        IntPtr cursor = minAddr;
        int mbiSize = Marshal.SizeOf(typeof(MEMORY_BASIC_INFORMATION));

        while (cursor.ToInt64() < maxAddr.ToInt64())
        {
            if (VirtualQueryEx(hProcess, cursor, out MEMORY_BASIC_INFORMATION mbi, mbiSize) != mbiSize) break;
            regionsScanned++;

            long regionSize = mbi.RegionSize.ToInt64();
            IntPtr regionBase = mbi.BaseAddress;

            if (regionSize > 1024L * 1024 * 1024 || !IsRegionScannable(mbi))
            {
                regionsSkipped++;
                cursor = new IntPtr(regionBase.ToInt64() + regionSize);
                continue;
            }

            int chunkSize = (int)Math.Min(regionSize, 500L * 1024 * 1024);
            var buffer = new byte[chunkSize];

            if (!ReadProcessMemory(hProcess, regionBase, buffer, chunkSize, out int bytesRead) || bytesRead == 0)
            {
                cursor = new IntPtr(regionBase.ToInt64() + regionSize);
                continue;
            }

            totalBytes += bytesRead;

            // ASCII
            for (int p = 0; p < asciiPatterns.Count; p++)
            {
                var pat = asciiPatterns[p];
                if (pat.Length == 0 || pat.Length > bytesRead) continue;
                int idx = IndexOf(buffer, pat);
                while (idx >= 0 && idx + pat.Length <= bytesRead)
                {
                    var addr = new IntPtr(regionBase.ToInt64() + idx);
                    if (OverwriteRemote(hProcess, addr, pat.Length, FillMode.Random)) asciiMatches++;
                    else writeFailures++;
                    idx = IndexOf(buffer, pat, idx + pat.Length);
                }
            }

            // UTF-16
            for (int p = 0; p < widePatterns.Count; p++)
            {
                var pat = widePatterns[p];
                if (pat.Length == 0 || pat.Length > bytesRead) continue;
                int idx = IndexOf(buffer, pat);
                while (idx >= 0 && idx + pat.Length <= bytesRead)
                {
                    var addr = new IntPtr(regionBase.ToInt64() + idx);
                    if (OverwriteRemote(hProcess, addr, pat.Length, FillMode.Random)) wideMatches++;
                    else writeFailures++;
                    idx = IndexOf(buffer, pat, idx + pat.Length);
                }
            }

            cursor = new IntPtr(regionBase.ToInt64() + regionSize);
        }

        sw.Stop();
        Console.WriteLine("[+] Done in " + sw.ElapsedMilliseconds + "ms");
        Console.WriteLine("    Matches: " + (asciiMatches + wideMatches) + " (ASCII:" + asciiMatches + " UTF16:" + wideMatches + ")");
        Console.WriteLine("    Regions: " + (regionsScanned - regionsSkipped) + "/" + regionsScanned + "  Bytes: " + (totalBytes / 1024 / 1024) + "MB");
        Console.WriteLine("\nPress any key to exit...");
        Console.ReadKey();
    }
}